	assert.Equal(t, nd.Id, d.Id)
	assert.Equal(t, nd.RuleId, d.RuleId)
	assert.Equal(t, nd.VariantId, d.VariantId)
	assert.InDelta(t, nd.Rollout, d.Rollout, 0)
